      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  const ports = ['BruteSSH.exe', 'FTPCrack.exe', 'RelaySMTP.exe', 'HTTPWorm.exe', 'SQLInject.exe'];\n  const openPort = (server, port) => {\n    if (port === 'BruteSSH.exe' && ns.fileExists(port, 'home')) ns.brutessh(server);\n    else if (port === 'FTPCrack.exe' && ns.fileExists(port, 'home')) ns.ftpcrack(server);\n    else if (port === 'RelaySMTP.exe' && ns.fileExists(port, 'home')) ns.relaysmtp(server);\n    else if (port === 'HTTPWorm.exe' && ns.fileExists(port, 'home')) ns.httpworm(server);\n    else if (port === 'SQLInject.exe' && ns.fileExists(port, 'home')) ns.sqlinject(server);\n  };\n  \n  const getReachable = (start) => {\n    let visited = new Set([start]);\n    let queue = [start];\n    while (queue.length > 0) {\n      let curr = queue.shift();\n      let neighbors = ns.scan(curr);\n      for (let n of neighbors) {\n        if (!visited.has(n)) {\n          visited.add(n);\n          queue.push(n);\n        }\n      }\n    }\n    return Array.from(visited);\n  };\n  \n  let servers = getReachable('home');\n  for (let server of servers) {\n    if (server === 'home') continue;\n    if (ns.hasRootAccess(server)) continue;\n    let portsNeeded = ns.getServerNumPortsRequired(server);\n    for (let port of ports) openPort(server, port);\n    if (ns.getServerNumPortsRequired(server) <= ports.filter(p => ns.fileExists(p, 'home')).length) {\n      ns.nuke(server);\n    }\n  }\n  \n  let target = null, maxProfit = 0;\n  for (let server of servers) {\n    if (server === 'home' || !ns.hasRootAccess(server)) continue;\n    if (ns.getServerRequiredHackingLevel(server) > ns.getHackingLevel()) continue;\n    let money = ns.getServerMaxMoney(server);\n    let sec = ns.getServerSecurityLevel(server);\n    let profit = money / (1 + sec);\n    if (profit > maxProfit) {\n      maxProfit = profit;\n      target = server;\n    }\n  }\n  \n  if (!target) target = 'n00dles';\n  \n  while (true) {\n    let sec = ns.getServerSecurityLevel(target);\n    let minSec = ns.getServerMinSecurityLevel(target);\n    let money = ns.getServerMoneyAvailable(target);\n    let maxMoney = ns.getServerMaxMoney(target);\n    \n    if (sec > minSec + 5) {\n      await ns.weaken(target);\n    } else if (money < maxMoney * 0.75) {\n      await ns.grow(target);\n    } else {\n      await ns.hack(target);\n    }\n  }\n}\n",
