      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  // Safely enumerate top-level ns properties\n  const skip = ['buy','sell','install','attack','hack','start','stop','purchase','upgrade','donate','crime','join','quit','destroy','nuke','bribe','kickFromFaction','murder','assassin'];\n  \n  function isSafe(name) {\n    const low = name.toLowerCase();\n    return !skip.some(s => low.includes(s));\n  }\n\n  const results = {};\n  \n  // Get all property names from ns\n  let props = [];\n  try {\n    props = Object.getOwnPropertyNames(ns);\n  } catch(e) {\n    props = Object.keys(ns);\n  }\n  \n  // Also try common names\n  const extras = ['help','docs','tutorial','print','tprint','scan','ls','ps','getHostname',\n    'getServerMaxMoney','getServerMoneyAvailable','getPlayerInfo','getPlayer','getCharacterInfo',\n    'getHackingLevel','getStats','getMoney','getBalance','getLevel','getUpgrades','getShop',\n    'getAugmentations','getPurchasableAugs','getTasks','getCrimes','getGang','sleeve',\n    'bladeburner','corporation','hacknet','stock','singularity','formulas','ui','args'];\n  \n  const allNames = [...new Set([...props, ...extras])];\n  \n  for (const key of allNames) {\n    try {\n      const val = ns[key];\n      if (val === undefined) continue;\n      const t = typeof val;\n      if (t === 'object' && val !== null) {\n        // Enumerate nested\n        const nested = {};\n        let subkeys = [];\n        try { subkeys = Object.getOwnPropertyNames(val); } catch(e) { subkeys = Object.keys(val); }\n        for (const sk of subkeys) {\n          try {\n            const sv = val[sk];\n            nested[sk] = typeof sv;\n          } catch(e) {\n            nested[sk] = 'error:' + e.message;\n          }\n        }\n        results[key] = { type: 'object', children: nested };\n      } else if (t === 'function') {\n        results[key] = { type: 'function' };\n      } else {\n        results[key] = { type: t, value: String(val).slice(0,100) };\n      }\n    } catch(e) {\n      results[key] = { error: e.message };\n    }\n  }\n  \n  // Print in chunks\n  const lines = JSON.stringify(results, null, 1).split('\\n');\n  for (let i = 0; i < lines.length; i += 20) {\n    ns.tprint(lines.slice(i, i+20).join('\\n'));\n  }\n}",
