      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  const servers = [];\n  const q = ['home'];\n  const seen = new Set(['home']);\n  \n  while (q.length) {\n    const curr = q.shift();\n    const neighbors = ns.scan(curr);\n    for (const n of neighbors) {\n      if (!seen.has(n)) {\n        seen.add(n);\n        q.push(n);\n        servers.push(n);\n      }\n    }\n  }\n  \n  const profiles = [];\n  for (const srv of servers) {\n    const maxMoney = ns.getServerMaxMoney(srv);\n    const growth = ns.getServerGrowth(srv);\n    if (maxMoney > 0 && ns.hasRootAccess(srv)) {\n      profiles.push({name: srv, maxMoney, growth});\n    }\n  }\n  \n  profiles.sort((a, b) => b.maxMoney / a.growth - a.maxMoney / b.growth);\n  \n  if (profiles.length === 0) {\n    ns.tprint('No hackable servers found');\n    return;\n  }\n  \n  const target = profiles[0].name;\n  ns.tprint(`Target: ${target}`);\n  \n  while (true) {\n    const sec = ns.getServerSecurityLevel(target);\n    const money = ns.getServerMoneyAvailable(target);\n    const maxMoney = ns.getServerMaxMoney(target);\n    const minSec = 1;\n    \n    if (sec > minSec + 5) {\n      await ns.weaken(target);\n    } else if (money < maxMoney * 0.8) {\n      await ns.grow(target);\n    } else {\n      await ns.hack(target);\n    }\n  }\n}",
