      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  // Analyze player stats and available upgrades\n  const player = ns.getPlayer();\n  const money = player.money;\n  \n  ns.tprint(`\\n=== Upgrade Analysis ===\");\n  ns.tprint(`Current Money: $${ns.formatNumber(money)}`);\n  ns.tprint(`Hacking Level: ${player.hacking}`);\n  ns.tprint(`Strength: ${player.strength}`);\n  ns.tprint(`Defense: ${player.defense}`);\n  ns.tprint(`Dexterity: ${player.dexterity}`);\n  ns.tprint(`Agility: ${player.agility}`);\n  ns.tprint(`Charisma: ${player.charisma}`);\n  ns.tprint(`Intelligence: ${player.intelligence}`);\n  \n  // Check if augmentations can be purchased\n  const augList = ns.singularity.getAugmentationsFromFaction(\"Tian Di Hui\");\n  \n  ns.tprint(`\\n=== Available Augmentations ===\");\n  for (const aug of augList) {\n    const cost = ns.singularity.getAugmentationCost(aug);\n    const stats = ns.singularity.getAugmentationStats(aug);\n    const affordable = money >= cost;\n    const status = affordable ? \"✓ AFFORDABLE\" : \"✗ Too expensive\";\n    \n    ns.tprint(`${aug}: $${ns.formatNumber(cost)} [${status}]`);\n    if (stats.hacking_mult) ns.tprint(`  → Hack: x${stats.hacking_mult}`);\n    if (stats.hacking_grow_mult) ns.tprint(`  → Grow: x${stats.hacking_grow_mult}`);\n    if (stats.hacking_chance_mult) ns.tprint(`  → Chance: x${stats.hacking_chance_mult}`);\n  }\n}",
