      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  // List all properties of ns\n  try {\n    const keys = Object.getOwnPropertyNames(ns);\n    ns.tprint('NS KEYS: ' + JSON.stringify(keys));\n  } catch(e) { ns.tprint('keys error: ' + e); }\n\n  // Try prototype methods\n  try {\n    const proto = Object.getOwnPropertyNames(Object.getPrototypeOf(ns));\n    ns.tprint('NS PROTO: ' + JSON.stringify(proto));\n  } catch(e) { ns.tprint('proto error: ' + e); }\n\n  // Try common getters safely\n  const probes = [\n    () => { const r = ns.getPlayer?.(); ns.tprint('getPlayer: ' + JSON.stringify(r)); },\n    () => { const r = ns.getServer?.('home'); ns.tprint('getServer home: ' + JSON.stringify(r)); },\n    () => { const r = ns.scan?.(); ns.tprint('scan: ' + JSON.stringify(r)); },\n    () => { const r = ns.ls?.('home'); ns.tprint('ls home: ' + JSON.stringify(r)); },\n    () => { const r = ns.getHostname?.(); ns.tprint('hostname: ' + r); },\n    () => { const r = ns.getServerMoneyAvailable?.('home'); ns.tprint('money home: ' + r); },\n    () => { const r = ns.getHackingLevel?.(); ns.tprint('hackLevel: ' + r); },\n  ];\n  for (const p of probes) {\n    try { p(); } catch(e) { ns.tprint('probe error: ' + e); }\n  }\n}",
