      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  const visited = new Set();\n  const scanQueue = ['home'];\n  const servers = [];\n  \n  // Scan network\n  while (scanQueue.length > 0) {\n    const srv = scanQueue.shift();\n    if (visited.has(srv)) continue;\n    visited.add(srv);\n    servers.push(srv);\n    const peers = ns.scan(srv);\n    for (const peer of peers) {\n      if (!visited.has(peer)) scanQueue.push(peer);\n    }\n  }\n  \n  // Try to gain root on all servers\n  for (const srv of servers) {\n    if (ns.hasRootAccess(srv)) continue;\n    const portsNeeded = ns.getServerNumPortsRequired(srv);\n    if (portsNeeded === 0) {\n      ns.nuke(srv);\n    } else if (portsNeeded === 1) {\n      ns.brutessh(srv);\n      ns.nuke(srv);\n    } else if (portsNeeded === 2) {\n      ns.brutessh(srv);\n      ns.ftpcrack(srv);\n      ns.nuke(srv);\n    }\n  }\n  \n  let lastRescan = 0;\n  \n  while (true) {\n    const now = Date.now();\n    \n    // Rescan every 60 seconds\n    if (now - lastRescan > 60000) {\n      lastRescan = now;\n      visited.clear();\n      scanQueue.length = 0;\n      scanQueue.push('home');\n      servers.length = 0;\n      \n      while (scanQueue.length > 0) {\n        const srv = scanQueue.shift();\n        if (visited.has(srv)) continue;\n        visited.add(srv);\n        servers.push(srv);\n        const peers = ns.scan(srv);\n        for (const peer of peers) {\n          if (!visited.has(peer)) scanQueue.push(peer);\n        }\n      }\n      \n      const myLevel = ns.getHackingLevel();\n      for (const srv of servers) {\n        if (ns.hasRootAccess(srv)) continue;\n        const req = ns.getServerRequiredHackingLevel(srv);\n        if (req > myLevel) continue;\n        \n        const portsNeeded = ns.getServerNumPortsRequired(srv);\n        if (portsNeeded === 0) {\n          ns.nuke(srv);\n        } else if (portsNeeded === 1) {\n          ns.brutessh(srv);\n          ns.nuke(srv);\n        } else if (portsNeeded === 2) {\n          ns.brutessh(srv);\n          ns.ftpcrack(srv);\n          ns.nuke(srv);\n        }\n      }\n    }\n    \n    // Find best target\n    let target = null;\n    let bestRatio = -1;\n    \n    for (const srv of servers) {\n      if (srv === 'home') continue;\n      if (!ns.hasRootAccess(srv)) continue;\n      \n      const max = ns.getServerMaxMoney(srv);\n      if (max === 0) continue;\n      \n      const minSec = ns.getServerMinSecurityLevel(srv);\n      if (minSec === 0) continue;\n      \n      const ratio = max / minSec;\n      if (ratio > bestRatio) {\n        bestRatio = ratio;\n        target = srv;\n      }\n    }\n    \n    if (!target) {\n      await ns.sleep(1000);\n      continue;\n    }\n    \n    const sec = ns.getServerSecurityLevel(target);\n    const minSec = ns.getServerMinSecurityLevel(target);\n    const money = ns.getServerMoneyAvailable(target);\n    const maxMoney = ns.getServerMaxMoney(target);\n    \n    if (sec > minSec + 5) {\n      ns.print(`Weakening ${target}, sec=${sec.toFixed(1)}`);\n      await ns.weaken(target);\n    } else if (money < maxMoney * 0.75) {\n      ns.print(`Growing ${target}, money=${money.toFixed(0)}/${maxMoney}`);\n      await ns.grow(target);\n    } else {\n      ns.print(`Hacking ${target}, money=${money.toFixed(0)}`);\n      await ns.hack(target);\n    }\n  }\n}\n",
