      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  const visited = new Set();\n  const servers = [];\n\n  async function scan(host) {\n    if (visited.has(host)) return;\n    visited.add(host);\n\n    const maxMoney = ns.getServerMaxMoney(host);\n    const curMoney = ns.getServerMoneyAvailable(host);\n    const minSec = ns.getServerMinSecurityLevel(host);\n    const curSec = ns.getServerSecurityLevel(host);\n    const reqHack = ns.getServerRequiredHackingLevel(host);\n    const maxRam = ns.getServerMaxRam(host);\n    const hasRoot = ns.hasRootAccess(host);\n\n    servers.push({\n      host,\n      maxMoney,\n      curMoney,\n      minSec,\n      curSec,\n      reqHack,\n      maxRam,\n      hasRoot\n    });\n\n    const neighbors = ns.scan(host);\n    for (const neighbor of neighbors) {\n      await scan(neighbor);\n    }\n  }\n\n  ns.tprint(`Hostname: ${ns.getHostname()}`);\n  await scan('home');\n\n  servers.sort((a, b) => b.maxMoney - a.maxMoney);\n\n  ns.tprint('\\n=== Servers (sorted by max money) ===');\n  for (const s of servers) {\n    ns.tprint(\n      `${s.host} | Max: $${(s.maxMoney / 1e9).toFixed(2)}b | ` +\n      `Cur: $${(s.curMoney / 1e9).toFixed(2)}b | ` +\n      `MinSec: ${s.minSec.toFixed(1)} | CurSec: ${s.curSec.toFixed(1)} | ` +\n      `ReqHack: ${s.reqHack} | RAM: ${s.maxRam.toFixed(2)}GB | ` +\n      `Root: ${s.hasRoot}`\n    );\n  }\n}\n",
