      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  const visited = new Set();\n  const queue = ['home'];\n  const servers = [];\n  \n  while (queue.length > 0) {\n    const host = queue.shift();\n    if (visited.has(host)) continue;\n    visited.add(host);\n    \n    try {\n      const maxMoney = ns.getServerMaxMoney(host);\n      const currentMoney = ns.getServerMoneyAvailable(host);\n      const minSecurity = ns.getServerMinSecurityLevel(host);\n      const currentSecurity = ns.getServerSecurityLevel(host);\n      const requiredLevel = ns.getServerRequiredHackingLevel(host);\n      const growth = ns.getServerGrowth(host);\n      const maxRam = ns.getServerMaxRam(host);\n      const hasRoot = ns.hasRootAccess(host);\n      \n      servers.push({\n        host,\n        maxMoney,\n        currentMoney,\n        minSecurity,\n        currentSecurity,\n        requiredLevel,\n        growth,\n        maxRam,\n        hasRoot\n      });\n      \n      const neighbors = ns.scan(host);\n      for (const neighbor of neighbors) {\n        if (!visited.has(neighbor)) {\n          queue.push(neighbor);\n        }\n      }\n    } catch (e) {\n      ns.print(`Error processing ${host}: ${e}`);\n    }\n  }\n  \n  const playerLevel = ns.getPlayer().hacking;\n  const summary = servers.map(s => \n    `${s.host}|${s.maxMoney}|${s.currentMoney}|${s.minSecurity}|${s.currentSecurity}|${s.requiredLevel}|${s.growth}|${s.maxRam}|${s.hasRoot ? 'Y' : 'N'}`\n  ).join(' ');\n  \n  ns.tprint(`PLAYER_LEVEL=${playerLevel} SERVERS=${summary}`);\n}",
