      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  const openPorts = [ns.brutessh, ns.ftpcrack, ns.relaysmtp, ns.httpworm, ns.sqlinject];\n  const visited = new Set();\n  const queue = ['home'];\n  const servers = [];\n  \n  // BFS to find all reachable servers\n  while (queue.length > 0) {\n    const curr = queue.shift();\n    if (visited.has(curr)) continue;\n    visited.add(curr);\n    servers.push(curr);\n    \n    const neighbors = ns.scan(curr);\n    for (const neighbor of neighbors) {\n      if (!visited.has(neighbor)) queue.push(neighbor);\n    }\n  }\n  \n  // Gain root access on all servers\n  for (const server of servers) {\n    if (ns.hasRootAccess(server)) continue;\n    \n    let portCount = 0;\n    for (const openPort of openPorts) {\n      try {\n        if (ns.fileExists(openPort.name.split('.')[0] + '.exe', 'home')) {\n          openPort(server);\n          portCount++;\n        }\n      } catch (e) {}\n    }\n    \n    if (portCount >= ns.getServerNumPortsRequired(server)) {\n      ns.nuke(server);\n    }\n  }\n  \n  // Main hacking loop\n  while (true) {\n    let bestServer = 'n00dles';\n    let bestMoney = 0;\n    const myHackLevel = ns.getHackingLevel();\n    \n    // Find best server to hack\n    for (const server of servers) {\n      if (!ns.hasRootAccess(server)) continue;\n      const reqLevel = ns.getServerRequiredHackingLevel(server);\n      if (reqLevel > myHackLevel) continue;\n      const maxMoney = ns.getServerMaxMoney(server);\n      if (maxMoney > bestMoney) {\n        bestMoney = maxMoney;\n        bestServer = server;\n      }\n    }\n    \n    const security = ns.getServerSecurityLevel(bestServer);\n    const minSecurity = ns.getServerMinSecurityLevel(bestServer);\n    const money = ns.getServerMoneyAvailable(bestServer);\n    const maxMoney = ns.getServerMaxMoney(bestServer);\n    \n    if (security > minSecurity + 5) {\n      await ns.weaken(bestServer);\n    } else if (money < maxMoney * 0.75) {\n      await ns.grow(bestServer);\n    } else {\n      await ns.hack(bestServer);\n    }\n  }\n}",
