      "script_sample": "/** @param {NS} ns */\nexport async function main(ns) {\n  const portOpeners = [\n    { name: 'BruteSSH.exe', fn: ns.brutessh },\n    { name: 'FTPCrack.exe', fn: ns.ftpcrack },\n    { name: 'RelaySMTP.exe', fn: ns.relaysmtp },\n    { name: 'HTTPWorm.exe', fn: ns.httpworm },\n    { name: 'SQLInject.exe', fn: ns.sqlinject }\n  ];\n\n  const scanServers = (start) => {\n    const visited = new Set();\n    const queue = [start];\n    const servers = [];\n    while (queue.length) {\n      const s = queue.shift();\n      if (visited.has(s)) continue;\n      visited.add(s);\n      servers.push(s);\n      const neighbors = ns.scan(s);\n      for (const n of neighbors) {\n        if (!visited.has(n)) queue.push(n);\n      }\n    }\n    return servers;\n  };\n\n  const gainRoot = (server) => {\n    let ports = 0;\n    for (const po of portOpeners) {\n      if (ns.fileExists(po.name, 'home')) {\n        po.fn(server);\n        ports++;\n      }\n    }\n    if (ns.fileExists('NUKE.exe', 'home')) {\n      ns.nuke(server);\n    }\n  };\n\n  const findBestServer = (servers) => {\n    let best = null;\n    let bestScore = -Infinity;\n    const myLevel = ns.getHackingLevel();\n    for (const srv of servers) {\n      if (!ns.hasRootAccess(srv)) continue;\n      const reqLevel = ns.getServerRequiredHackingLevel(srv);\n      if (reqLevel > myLevel) continue;\n      const maxMoney = ns.getServerMaxMoney(srv);\n      const sec = ns.getServerSecurityLevel(srv);\n      const score = maxMoney / (sec + 1);\n      if (score > bestScore) {\n        bestScore = score;\n        best = srv;\n      }\n    }\n    return best;\n  };\n\n  const servers = scanServers('home');\n  for (const srv of servers) {\n    if (srv === 'home') continue;\n    gainRoot(srv);\n  }\n\n  while (true) {\n    const best = findBestServer(servers);\n    if (!best) {\n      await ns.sleep(1000);\n      continue;\n    }\n    const maxMoney = ns.getServerMaxMoney(best);\n    const money = ns.getServerMoneyAvailable(best);\n    const sec = ns.getServerSecurityLevel(best);\n    const minSec = ns.getServerMinSecurityLevel(best);\n    if (sec > minSec + 5) {\n      await ns.weaken(best);\n    } else if (money < maxMoney * 0.75) {\n      await ns.grow(best);\n    } else {\n      await ns.hack(best);\n    }\n  }\n}\n",
