      "script_sample": "// Agent 1 Level 1 - Agent 002 Collaboration\n// Max lines: 50, Token budget: 2000\n\nasync function startLevel1() {\n  // Initialize level 1 state\n  if (!global.level1State) {\n    global.level1State = { completed: false, agentsReady: false };\n  }\n  \n  // Check if agent_002 is ready for collaboration\n  const agent002Ready = await checkAgentStatus(2);\n  const selfReady = await checkAgentStatus(1);\n  \n  // If agent_002 isn't ready, wait and retry\n  while (!agent002Ready || !selfReady) {\n    await wait(1000);\n    const ready = await checkAgentStatus(2);\n    const self = await checkAgentStatus(1);\n    agent002Ready = ready;\n    selfReady = self;\n    if (ready && self) break;\n  }\n  \n  // Start collecting resources for level 1\n  await collectItem('wood', 5);\n  await collectItem('metal', 5);\n  \n  // Open necessary doors for level 1\n  await openDoor(1);\n  await openDoor(2);\n  \n  // Coordinate with agent_002 on progress\n  await shareProgress(2);\n  await syncAgents();\n  \n  // Complete level 1 objective\n  await completeObjective('level1');\n  global.level1State.completed = true;\n  await finishLevel(1);\n}\n\nasync function checkAgentStatus(id) {\n  // Ensure agent_002 is ready to collaborate\n  const status = await getAgentStatus(id);\n  if (!status.ready) {\n    await waitUntilAgentReady(id);\n  }\n  return status.ready;\n}\n\nasync function shareProgress(targetId) {\n  // Share current level 1 progress with agent_002\n  const levelProgress = getLevelProgress();\n  await broadcastMessage('Level1', levelProgress, targetId);\n}\n\nasync function syncAgents() {\n  // Ensure both agents are in sync for level 1\n  await awaitAgentSync();\n}\n\nasync function shareData(agentId) {\n  const data = {\n    level: 1,\n    wood: await getInventoryCount('wood'),\n    metal: await getInventoryCount('metal'),\n    objectives: await getCompletedObjectives()\n  };\n  await sendMessage(2, JSON.stringify(data));\n}\n\nmodule.exports = {\n  startLevel1,\n  shareProgress,\n  syncAgents,\n  shareData\n};",
